def solve(N):
    f = [False] * (N + 1)
    # f[n] is True if the player whose turn it is to write a number after n has been written can win.
    # The moves from n are m = n+1 or m = 2n, provided m <= N.
    # If any m == N, f[n] = True.
    # If any m < N and f[m] == False, f[n] = True.
    # Otherwise, f[n] = False.

    for n in range(N - 1, 0, -1):
        can_win = False
        # check m = n+1
        m1 = n + 1
        if m1 == N:
            can_win = True
        elif m1 < N:
            if not f[m1]:
                can_win = True

        # check m = 2n
        if not can_win:
            m2 = 2 * n
            if m2 == N:
                can_win = True
            elif m2 < N:
                if not f[m2]:
                    can_win = True
        f[n] = can_win

    # N is type B if B can win after A writes 1.
    # B is the player whose turn it is to write after 1.
    # So N is type B if f[1] is True.
    return f[1]

for N in range(2, 100):
